    "abstractSummaryId": "Objective: Rumination is considered as a key process in the mechanism of depression. Assessing rumination is important for both research and clinical practice. The Ruminative Response Scale (RRS) is a widely-used instrument to measure rumination. This study aimed to examine the psychometric properties of the Chinese 10-item Ruminative Response Scale (RRS-10) in a large sample of Chinese undergraduates and depressive patients. Methods: A total of 1,773 university students and 286 clinical patients with major depressive disorder finished the Chinese version of the RRS10, State Trait Anxiety Inventory (STAI), and...",
