    "abstractSummaryId": "Background: The Patient Health Questionnaire (PHQ-9) is a popular tool for assessing depressive symptoms in both general and clinical populations. The present study used a large representative sample of the German adult population to confirm desired psychometric functioning and to provide updated population norms. Methods: The following psychometric properties were assessed: (i) Item characteristics (item means, standard deviations and inter-item correlations), (ii) Construct validity (correlations of the PHQ-9 sum-score with scores obtained from instruments assessing depression, anxiety and somatization (GAD-...",
