    "abstractSummaryId": "The present study examined the psychometric properties of the Chinese version of the Trait Emotional Intelligence Questionnaire Short Form (TEIQue-SF). Analyses were performed using a sample of undergraduates (N=585) recruited from four universities across China. Confirmatory factor analysis of the Chinese TEIQue-SF supported the one-factor structure of trait emotional intelligence. Measurement invariance analyses were conducted across the Chinese sample and a sample of Canadian undergraduate students (N=638). Although the two samples demonstrated configural and partial metric invariance, scalar invariance was...",
