    "abstractSummaryId": "Social media addiction has been a hot issue in scientific research in recent years, its antecedents and consequences have been extensively studied. Among these studies, Bergen Social Media Addiction Scale (BSMAS) is one of the most commonly used instruments. However, little is known about whether this scale has the equivalent psychometric properties for men and women. The purpose of the current study is to examine the measurement invariance (including configural invariance, metric invariance, scalar invariance, and error variance invariance) of the BSMAS across genders. In total, 1,120 participants were recrui...",
