    "sampleContext": "Detail jumlah & karakteristik partisipan tercantum lengkap pada teks penuh artikel DOI",
    "keyFindings": [
      "R program was applied to conduct the single-group and multiple-group confirmatory factor analysis (CFA) based on the social media addiction symptom ratings.",
      "The results demonstrated that BSMAS was a valid and psychometrically robust instrument for assessing the risk of social media addiction among university students, and that the four types of measurement invariance of the BSMAS across genders were confirmed.",
      "Consequently, gender differences in the BSMAS scores are likely to reflect the genuine differences between men and women, and comparisons on the level of social media addiction of university students between gender groups can be interpreted meaningfully."
    ],
