    "abstractSummaryId": "Purpose: Currently, information on the psychometric properties of the Medical outcomes study-social support survey (MOS-SSS) for patients with chronic disease in primary health care, suggests problems in the dimensionality, specifically predominant unidimensionality in a multidimensional measure. The aim of this study was to determine the internal structure (dimensionality, measurement invariance and reliability) and association with other variables. Methods: A total of 470 patients with chronic disease from a Family Medicine Unit at the Instituto Mexicano del Seguro Social, IMSS, with a mean age of 51.51 year...",
