    "sampleContext": "Detail jumlah & karakteristik partisipan tercantum lengkap pada teks penuh artikel DOI",
    "keyFindings": [
      "Results: Non-parametric (Mokken scaling analysis) and parametric (confirmatory factor analysis) analyses indicated unidimensionality, and three-factor model was not representative.",
      "A new 8-item version (MOS-S) was developed, where measurement invariance, equivalence with the long version, reliability, and relationship with the SF-36 were satisfactory.",
      "Conclusion: The MOS-SSS scale is unidimensional, and the shortened version yields valid and reliable scores for measuring social support in patients with chronic disease at the primary health care."
    ],
