    "abstractSummaryId": "Background Young adults in Hong Kong are subject to elevated psychological distress given the societal stressors such as civil unrest and COVID-19 pandemic and suicide is a leading cause of death among them. The present study aimed to evaluate the psychometric properties and measurement invariance of the 4-item Patient Health Questionnaire-4 (PHQ-4) as a brief measure of psychological distress and its associations with meaning in life and suicidal ideation (SI) in young adults. Materials and methods A mobile survey recruited a large and random sample of 1,472 young adults (Mean age = 26.3 years, 51.8% males) i...",
