    "abstractSummaryId": "Purpose: The Childhood Trauma Questionnaire-Short Form (CTQ-SF) is a widely used self-report tool designed to assess juveniles' experiences of abuse and neglect. The current study examined the psychometric properties, particularly measurement invariance of the CTQ-SF in Chinese non-clinical adolescents and adolescents with major depressive disorder (MDD). Methods: Participants included 1,507 high school students (non-clinical sample) from Hunan Province and 281 adolescent patients with major depressive disorder (MDD sample) from The Second Xiangya Hospital. We examined the reliability and validity of CTQ-SF, c...",
