    "abstractSummaryId": "Strengths, Opportunities, Aspirations, and Results (SOAR) is a strengths-based framework for strategic thinking, planning, conversations, and leading that focuses on strengths, opportunities, aspirations, and results. The SOAR framework leverages and integrates Appreciative Inquiry (AI) to create a transformation process through generative questions and positive framing. While SOAR has been used by practitioners since 2000 as a framework for generating positive organizational change, its use in empirical research has been limited by the absence of reliable and valid measures. We report on the reliability, cons...",
