    "abstractSummaryId": "Despite the well-established protective functions of positivity (i.e., a dispositional self-evaluative tendency to view oneself, life, and future under a positive outlook) from middle adolescence to old age, its reliable assessment and contribution to a proper psychological functioning have received little attention during previous developmental phases. In this article, we aimed to evaluate the psychometric properties and construct validity of the eight-item Positivity Scale (P Scale; Caprara et al., 2012) during late childhood and early adolescence in a sample of British students (N = 742; 48% boys) from both...",
