    "abstractSummaryId": "Artificial intelligence (AI) attitude scales can be used to better evaluate the benefit and drawback cons of AI. This article consists of two different studies examining attitudes towards AI. In Study I (N = 370), the four-item Artificial Intelligence Attitude Scale-4 (AIAS-4) has a one-dimensional structure as a result of confirmatory factor analysis and the fit index values ​​are at an acceptable level [Comparative Fit Index (CFI) = 0.991; Goodness of Fit Index (GFI) = 0.989; Normed Fit Index (NFI) = 0.988; Tucker-Lewis Index (TLI) = 0.973; Standardized Root Mean Square Residual (SRMR) = 0.018]. Additionally...",
