    "abstractSummaryId": "Introduction: The Generalized Anxiety Disorder-7 (GAD-7) scale is widely used to assess generalized anxiety symptoms in both clinical and general populations. However, updated psychometric evaluations and population norms for the German adult population are lacking. This study aims to examine the psychometric properties of the GAD-7 and provide representative population norms. Methods: A representative sample of the adult population in Germany (N = 2,519) was assessed. Item characteristics (means, standard deviations, inter-item correlations) were examined. Construct validity was evaluated through correlations...",
