    "abstractSummaryId": "BACKGROUND: The construct of meaningful work (MW) has become the subject of various studies. Workers who experience MW have higher career and organizational commitment, report fewer days absent, and are characterized by a higher level of well-being. The aim of this study is to test a measure of MW, the Work and Meaning Inventory by Steger et al. This measure was created on theoretical background, and it constructs MW from three dimensions: psychological meaning, meaning-making, and greater good motivation. METHODS: The analysis was conducted in a Hungarian sample (N = 2,498), using confirmatory factor analysis...",
