    "sampleContext": "Tercatat dalam abstrak artikel: N = 2,498 (lihat detail kriteria sampel pada artikel asli)",
    "keyFindings": [
      "Moreover, the discriminant and convergent validity of the WAMI was tested, with various relevant constructs: the presence and the search for life meaning, life satisfaction, and job satisfaction.",
      "Also a multiple-group CFA was conducted with the three-factor model, confirming measurement invariance regarding sex and working position.",
      "CONCLUSIONS: In line with the original version of the WAMI, the three-dimensional model was confirmed, with good psychometric properties in the Hungarian working context."
    ],
