    "sampleContext": "Detail jumlah & karakteristik partisipan tercantum lengkap pada teks penuh artikel DOI",
    "keyFindings": [
      "The CFA demonstrated measurement invariance across gender, school year and country of birth, which was also confirmed by Rasch DIF.",
      "Furthermore, considerable associations between the items of the SWEMWBS, general health and COVID-19 impact items were observed in network analysis.",
      "The SWEMWBS showed robust psychometric properties capable of assessing positive aspects of mental health and well-being among adolescents."
    ],
