    "abstractSummaryId": "The concept of rule-governed behavior (RGB) has been used in the behavior-analytic literature as a way to analyze complex human behavior, including thinking and problem-solving. Relational frame theory suggests the existence of two main functional types of RGB termed pliance and tracking. In this paper, we describe the development of the Generalized Tracking Questionnaire (GTQ) and the preliminary evaluation of its psychometric properties and validity through three studies, with a total of 1155 participants. In Study 1, a pool of items describing the main characteristics of generalized tracking was designed an...",
    "methodology": "Studi Psikometri & Validasi Instrumen (CFA/EFA/IRT)",
    "sampleContext": "Detail jumlah & karakteristik partisipan tercantum lengkap pada teks penuh artikel DOI",
    "keyFindings": [
      "In Study 3, the GTQ and a neuropsychological battery of executive functions were administered to 105 participants.",
      "The GTQ showed statistically significant, medium-size correlations with working memory tests, verbal fluency, planning, and behavioral inhibition.",
      "In conclusion, the GTQ seems to be a promising measure to advance in the empirical analysis of functional classes of RGB."
    ],
