    "abstractSummaryId": "The 5-item Generic Conspiracist Beliefs Scale (GCB-5) is an abridged version of the 15-item GCBS. It was developed as a global measure of the tendency to engage in non-event-based, conspiracy-related ideation. The GCB-5 is appealing to researchers because of its brevity, which facilitates the measurement of belief in conspiracies alongside multiple constructs and/or in situations where resources are limited (time, etc.). Noting that several studies failed to find an adequate unidimensional fit in the parent GCBS measures across different contexts, the present study further assessed the psychometric properties...",
    "methodology": "Studi Psikometri & Validasi Instrumen (CFA/EFA/IRT)",
