    "keyFindings": [
      "The GCB-5 also demonstrated configural, metric, and scalar invariance (among gender and age subgroups).",
      "This indicated that the GCB-5 was interpreted similarly by men and women and different age groups.",
      "Overall, results supported the assertion that the GCB-5 is a psychometrically satisfactory global measure of non-event-based, conspiratorial ideation."
    ],
