    "abstractSummaryId": "BACKGROUND: This study aims to validate and evaluate the psychometric properties and measurement invariance of the Italian version of the European Organization for Research and Treatment of Cancer (EORTC) Quality of Life Questionnaire-Core 30 (QLQ-C30), which is a measure of quality of life (QoL) for lung cancer patients after surgery. METHODS: A total of 167 lung cancer patients completed the Italian version of the EORTC QLQ-C30 questionnaire at 30 days after they received a lobectomy. The factor structure of this scale was assessed by performing confirmatory factor analysis (CFA). Measurement invariance was...",
    "methodology": "Studi Psikometri & Validasi Instrumen (CFA/EFA/IRT)",
