    "abstractSummaryId": "BACKGROUND: The sense of coherence is as focused on one's awareness of the level of pervasive, enduring, and dynamic feelings. Stronger sense of coherence leads to better physical and mental health and promotes recovery from life stressors. Sense of coherence-13 (SOC-13) is a 13-item valid and reliable measure for individual's healthy living. However, the factor structure of SOC-13 was criticized in several cultures and languages. The current study was set to explore the factor structure of an Arabic adaptation for SOC-13. METHODS: This cross-sectional study of the SOC-13 included (n = 1235) Arabic speaking in...",
