    "abstractSummaryId": "Objective: Impulsivity is widely recognized as a risk factor for a variety of mental disorders and problematic behaviors. The Short UPPS-P Impulsive Behavior Scale (SUPPS-P) is an extensively used instrument to measure impulsivity in research and clinical settings. The current study primarily aimed to evaluate the psychometric properties of the Chinese version of the SUPPS-P (C-SUPPS-P) among Chinese adolescents and young adults, and then to test its measurement invariance across gender and age. Methods: Data were collected from three vocational high schools and six colleges in Changsha, China. A total of 2,55...",
