    "abstractSummaryId": "Introduction: Psychological tests are necessary to assess the mental state of individuals. Mental health is one of the important psychological indicators and is increasingly considered as having various aspects of well-being. The Mental Health Continuum-Short Form (MHC-SF) is a 14-item instrument that assesses mental health, focusing on emotional, psychological, and social well-being. The present study, the psychometric properties of the Persian version of the MHC-SF were examined in relation to its factor structure, internal consistency, construct validity, and gender measurement invariance among adolescents....",
    "methodology": "Studi Psikometri & Validasi Instrumen (CFA/EFA/IRT)",
