    "keyFindings": [
      "In addition, with the strict invariance requirements being satisfied, the underlying factor scores for MPAI can be meaningfully compared across genders.",
      "To our knowledge, this study is the first attempt to test the measurement invariance of the MPAI across male and female adolescents.",
      "Our results will support future research on mobile phone addiction in adolescents."
    ],
