    "sampleContext": "Detail jumlah & karakteristik partisipan tercantum lengkap pada teks penuh artikel DOI",
    "keyFindings": [
      "The student teachers' unethical professional behavior tendencies scale correlated negatively with their professional ethical values and positively with perceived frequency of unethical professional behaviors of college teachers around them.",
      "The data supported the scale's measurement invariance across gender, and male student teachers scored significantly higher on unethical professional behavior tendencies than female student teachers.",
      "The findings suggest that the student teachers' unethical professional behavior tendencies scale is a useful instrument for assessing student teachers' unethical professional behaviors in China."
    ],
