    "abstractSummaryId": "To address the need for a valid and reliable scale of youth leadership potential based on the development theory of leadership, the current study developed the Youth Leadership Potential Scale (YLPS) and investigated its factor structure and psychometric properties in a sample of 696 students (grades 7-9) in China. Exploratory structural equation modeling (ESEM) identified a five-factor solution comprising leadership information, leadership attitude, communication skills, decision-making skills, and stress management skills. ESEM within confirmatory factor analysis demonstrated an adequate fit for this structu...",
