    "abstractSummaryId": "BACKGROUND: Primary schoolteachers play a pivotal role in the education of children, highlighting the importance of addressing their psychological well-being and mental health. While the Depression, Anxiety, and Stress Scale-21 (DASS-21) is a globally recognized instrument for evaluating mental health, its systematic validation among primary schoolteachers, particularly in a cross-national context, remains understudied. The present cross-cultural study evaluated the psychometric properties of DASS-21 among primary schoolteachers in Spain and China to compare the DASS-21 between teachers across Western and East...",
