    "abstractSummaryId": "BACKGROUND: Based on the self-determination theory, the psychological requirements for competence, autonomy, and relatedness boost beneficial exercise behaviour for healthy living. However, there is no valid, reliable Malay version scale to investigate the extent to which these psychological needs are met. The main purpose of this study was to examine the psychometric properties of a Malay version of the Psychological Need Satisfaction in Exercise (PNSE-M) scale. In addition, the purpose of this study was to confirm the measurement and structural invariance of the PNSE-M across gender. METHODS: The study parti...",
