    "abstractSummaryId": "Debilitating symptoms of fatigue and accompanying \"brain fog\" are observed among patients with various chronic health conditions. Unfortunately, an efficient and psychometrically sound instrument to assess these co-occurring symptoms is unavailable. Here, we report the development and initial psychometric properties of the Fatigue and Altered Cognition Scale (the FACs), a measure of self-reported central fatigue and brain fog. Traumatic brain injury (TBI) was chosen to model and develop the FACs due to research team expertise and established links between TBI and the symptom complex. Potential items were gener...",
