    "abstractSummaryId": "Background: , fifth edition. The ODI has been validated in English, French, and Spanish. This study (a) investigated the psychometric and structural properties of the ODI's Italian version and (b) inquired into the nomological network of occupational depression. Methods: A convenience sample of 963 employed individuals was recruited in Italy (69.9% female; mean age = 40.433). We notably relied on exploratory structural equation modeling bifactor analysis, common-practice confirmatory factor analysis, and Mokken scale analysis to examine our dataset. Results: Our analyses indicated that the Italian version of t...",
