    "abstractSummaryId": "There is a lack of available valid assessment tools (published) for assessing social anxiety symptoms among Bangladeshi people. Therefore, this study was aimed to examine the psychometric properties of the Social Anxiety Scale for Adolescents (Short Form) to assess the social anxiety symptoms among Bangladeshi young adults. In this study, the data ( N = 683) from the ‘Social Media Addiction among University Students' project were utilized. Results regarding item-level information using classical test theory and item response theory demonstrated that all items of the scale had a higher discrimination index and...",
