    "abstractSummaryId": "Job satisfaction is related to better physical and mental health, as well as to factors specifically related to work. In this context, the measurement of work satisfaction is important for organizations that profess an interest in engaged and satisfied workers. Therefore, this study aims to examine the psychometric properties of the Satisfaction with Job Life Scale (SWJLS) in Portuguese workers by combining the procedures of the Classical Test Theory (CTT) and the Item Response Theory (IRT). Specifically, internal structure of the scale was studied, its reliability (consistency), correlations with other measur...",
