    "abstractSummaryId": "BACKGROUND: Workplace telepressure and private life telepressure refer to the preoccupation with and the urge to respond quickly to electronic messages from people at work or in private life, respectively. We aimed to adapt and validate workplace and private life telepressure measures in French and to explore their nomological networks and relationships with psychological health and wellbeing. METHODS: Participants were recruited via flyers, local press, and social media to complete two online surveys. Participants had to be French-speaking employees working in Switzerland and regularly using information and c...",
