    "abstractSummaryId": "Introduction: The PERMA model of well-being has gained prominence in the study of well-being by the Positive Psychology movement. However, the model has been little studied regarding its applicability in different populations, such as adolescents. This study sought to evaluate the psychometric properties of the PERMA-Profiler instrument for Brazilian adolescents, as well as the measurement invariance for different age groups and gender, and investigate the relation with external variables. Methods: Confirmatory Factor Analysis and Multigroup Confirmatory Factor Analysis were used to test the internal structure...",
