    "abstractSummaryId": "Introduction: The Sport Anxiety Scale-2 (SAS-2) is a validated measure of sports trait anxiety, with promising psychometric properties. However, its cross-cultural applicability in Chinese samples remains unexplored. Thus, the primary objectives of this study were twofold: to translate the SAS-2 into Chinese and assess the psychometric properties of the Chinese version. Methods: In Study 1, we initiated the translation of the SAS-2 into Chinese. This assessment involved bilingual Chinese students proficient in both English and Chinese. Additionally, we conducted a cross-linguistic measurement invariance analys...",
