    "keyFindings": [
      "Moreover, we identified measurement invariance of the Chinese version of the SAS-2 across genders.",
      "Finally, female college athletes exhibited significantly higher scores in somatic anxiety and worry compared to their male counterparts.",
      "Discussion: In sum, our findings affirm that the Chinese version of the SAS-2 demonstrates robust reliability and correlates effectively with related criteria, thus validating its suitability for use in a Chinese context."
    ],
