    "abstractSummaryId": "OBJECTIVE: The Self-Importance of Moral Identity Scale (SMIS) was developed by Aquino and Reeds with the purpose of measuring how people evaluate their private (Internalization subscale) and public (Symbolization subscale) moral identity. SMIS has become commonly and broadly used in many studies. The aim of this paper is to validate the Polish version of SMIS by analyzing its structure and relation to similar measures (such as The Moral Self-Concept Scale developed by Stake and The Moral Self-Image Scale created by Jordan, Leliveld and Tenbrunsel), declared past prosocial behaviors and readiness to donate mone...",
