    "abstractSummaryId": "Introduction TheFear of Pain Questionnaire-III(FPQ-III) is a self-assessment instrument developed specifically to measure fear based on various pain stimuli converging on three factors: severe pain, medical pain, and minor pain. It actually remains the most studied and internationally used tool even in its short versions. The aim of this work was to propose a new validation study oriented to confirm the good psychometric properties of a short model of the FPQ-III for the Italian context. Methods A large sample of participants was recruited (n = 1,064) and Exploratory Factor Analysis (EFA) as well as Confirmato...",
