    "abstractSummaryId": "Mood assessment is an effective way to monitor mental health states and detect potential psychiatric symptoms. The Brunel Mood Scale (BRUMS) is one of the most widely used self-report measures for assessing mood responses. The current study examined the psychometric properties of the Bangla version of BRUMS and validated it with the Positive Mental Health scale (PMH-scale). The participants were 1015 Bangladeshi university students (62% men) aged from 18 to 27 ( M = 21.95, SD = 1.95). The confirmatory factor analysis (CFA) approach was used to test the factor structure of the BRUMS and measurement invariance f...",
