    "abstractSummaryId": "Although romantic relationships have been found to boost well-being, some studies demonstrated that staying single has similar beneficial effects. One cause of such contradiction is probably due to the lack of a quantitative measurement of attitudes toward singlehood. To address this methodological gap, four studies involving 1,276 undergraduate students in Malaysia and India were conducted to develop and examine the psychometric qualities of the Attitudes toward Singlehood Scale (AtSS). Study 1 selected 15 items from the pool and identified a 3-factor solution using exploratory factor analysis. However, a 9-i...",
