    "abstractSummaryId": "Introduction The World Health Organization-Five Well-Being Index (WHO-5) is a widely used self-report measure for evaluating mental well-being in both general and clinical populations. This study examines the psychometric properties of the WHO-5 using a large, representative sample of the adult population in Germany (N = 2,515) and presents updated population norms. Methods Analyses included item-level statistics such as means, standard deviations, and inter-item correlations. Construct validity was evaluated through correlations with measures of depression (PHQ-2), anxiety (GAD-2), somatic symptoms (SSS-8), a...",
