    "abstractSummaryId": "BACKGROUND: There is a dearth of research on religiosity in Arabic-speaking populations, partly due to a lack of universal, standardized and valid instruments to assess this construct. We sought through this study to establish the psychometric properties of an Arabic translation of the shortest version of the Central Religiosity Scale (CRS-5), a widely used measure of religiosity that can be applicable to most religious traditions, thus allowing for worldwide cultural and trans-religious comparisons. METHOD: A total of 352 Lebanese young adults enrolled in this study with a mean age of 25.08 years (SD = 9.25)...",
