    "abstractSummaryId": "Introduction Social emotional competence is fundamental to the positive development of children and youth. Accurately understanding and assessing children’s social emotional competencies, using psychometrically sound instruments, are essential to global efforts to support children’s social emotional learning, academic achievements, and health. This study examined the psychometric properties of a teacher-reported measure of young children’s social emotional competence, the Social Competence Scale – Teacher edition (SCS-T), in two samples of children growing up with varied economic resources/conditions, cultural...",
