    "abstractSummaryId": "The current study aimed to verify the multidimensional factor structure of teacher reflection and to examine the psychometric properties of a widely used teacher reflection scale using a large-scale representative dataset of 1,611 practicing Iranian English as a Foreign Language (EFL) teachers. Furthermore, the measurement invariance of the hypothesized,a priorisix-factor model of teacher reflection as measured by the adapted scale was assessed across gender and educational degree in Mplusprogram. In addition, the differences in latent factor means of the same groups were examined. The result of confirmatory f...",
