    "abstractSummaryId": "BACKGROUND: The ATQ is a widely used instrument consisting of 30 items that assess the frequency of negative automatic thoughts. However, the extensive length of the ATQ could compromise its measurement efficiency in survey research. Consequently, an 8-item shortened version of the ATQ has been developed. This study aims to analyze the validity of the ATQ-8 in two Spanish samples. METHOD: The ATQ-8 was administered to a total sample of 1,148 participants (302 undergraduates and 846 general online population). To analyze convergent construct validity, the questionnaire package also included the Dysfunctional At...",
