      "The ATQ-8 showed scalar metric invariance across samples, gender, groupage, and education level.",
      "The ATQ-8 scores were significantly associated with emotional symptoms (DASS-21), satisfaction with life (SWLS), dysfunctional schemas (DAS-R), cognitive fusion (CFQ), experiential avoidance (AAQ-II), and generalized pliance (GPQ).",
      "In conclusion, the Spanish version of the ATQ-8 demonstrated adequate psychometric properties in Spanish samples."
