    "abstractSummaryId": "The aim of the present study was to assess the psychometric properties of the Existential Quest (EQ) Scale, a nine-items instrument developed to assess openness to changing one's own convictions concerning existential issues. We developed the Italian version of the scale and examined factorial structure, internal consistency, discriminant validity, and measurement invariance across gender and age groups. A total of 291 Italian adults were recruited, and they completed a self-report questionnaire comprising measures of authoritarianism, cognitive closure, well-being, and religiousness, alongside the EQ. Confirm...",
