    "abstractSummaryId": "BACKGROUND: Resilience is conceptualized as an individual's ability to endure and bounce back from adversity. It serves as a crucial protective element for personal development within society, enabling individuals to navigate challenges successfully. The Brief Resilience Scale (BRS) is a widely used and freely available tool for measuring resilience. However, there is a lack of literature on its psychometric properties in the context of Indian college students. METHODS: A total of 211 Indian college students (M = 19.29 years, SD = 1.46 years) were recruited through non-probabilistic sampling to complete the Br...",
