    "abstractSummaryId": "Problematic smartphone use (PSU) is a global issue associated with numerous adverse outcomes, especially among young people. One of the most widely used instruments to evaluate PSU is the Smartphone Addiction Scale-Short Version (SAS-SV). This study examined the psychometric properties of the Spanish version of the SAS-SV, including factorial validity, convergent validity, divergent validity, and reliability. The final sample comprised 530 students from a university in Honduras. Confirmatory factor analysis provided evidence supporting the validity of the instrument's internal structure. Reliability was estima...",
