    "abstractSummaryId": "The Profile of Mood States (POMS) is one of the most widely applied scales for measuring mood. Considering the advantages of short scales and increased international research, the aim of the present study was to evaluate cross-culturally the psychometric properties of a short 16-item version of the POMS. Data were collected from 15,693 participants across 10 different countries worldwide. Initially, we identified the original versions of the POMS in various languages. Subsequently, we selected 16 items based on the previously validated short form (POMS-16) for analysis. Psychometric properties of the POMS were...",
