    "abstractSummaryId": "The family is one of the most important pillars of society. They provide strong feelings of security, emotional support, and belonging. Family health has a significant impact on the welfare of people and society as a whole. This study aimed to create the Satisfaction with Family Life Scale (SWFLS) for Türkiye by modifying the well-known Satisfaction with Life Scale (SWLS) first developed by Diener et al. (1985) and to evaluate its psychometric properties. The present study examined the factor structure, measurement invariance, convergent validity, and internal consistency of the SWFLS. Confirmatory factor anal...",
