    "abstractSummaryId": "Background: The COVID-19 pandemic has created a public mental health crisis. Brief, valid electronic tools are required to evaluate mental health status, identify specific risk factors, and offer treatment when needed. Objective: To determine the construct validity, reliability, and measurement invariance of a brief screening tool for mental health symptoms by sex, loss of loved ones, personal COVID-19 status, and psychological care-seeking during the COVID-19 pandemic. Furthermore, the aim involved establishing a predictive pattern between the mental health variables. Method: = 5,026), completed a questionnai...",
