    "abstractSummaryId": "In contemporary workplaces characterized by diverse age groups working collaboratively, the assessment of age discrimination as an interpersonal phenomenon has gained heightened significance. This study focuses on adapting and scrutinizing the psychometric properties of the German iteration of the Workplace Age Discrimination Scale (WADS-G). Comprehensive Confirmatory Factor Analysis (CFA) results affirm a robust fit for the unidimensional model. Convergent validity is established through correlations between WADS-G scores and related instruments, while discriminant validity is evidenced by its lack of associa...",
    "methodology": "Studi Longitudinal",
