    "abstractSummaryId": "BACKGROUND: Work addiction (WA) threatens occupation-related health in many countries including China. This research aims to evaluate the psychometric properties of the Chinese version of Bergen Work Addiction Scale (BWAS), the most common measure of WA, to facilitate relevant studies in Chinese workers. A network analysis was further conducted to identify central and bridge symptoms within the WA-anxiety network to improve intervention practices. METHODS: A total of 694 Chinese white-collar workers completed an online questionnaire survey in March of 2022, and the responses to BWAS from a subsample of 50 part...",
