    "abstractSummaryId": "Background English is a global language used to communicate with members of the international community. Self-efficacy in learning English is an important factor that is influenced by perceived importance, interest, and beliefs about the ability to successfully perform tasks in English. Objective The aim is to develop and validate a measurement instrument to assess English self-efficacy. Methods A total of 453 students from different Peruvian universities participated, with ages ranging from 18 to 60 years (M = 23; SD = 6.18). Statistical techniques for latent variables were used and recommendations for educat...",
