    "abstractSummaryId": "BACKGROUND: The Penn Alcohol Craving Scale (PACS) is an instrument with good psychometric properties that is widely used to assess alcohol craving. Based on the assumption that the experience of craving is independent of substance type, the Polish version of the PACS was modified to measure drug craving, thus creating the Penn Drug Craving Scale (PDCS). The analyses presented in the paper aim to verify the hypothesis that the PDCS has a unidimensional structure, is highly reliable and features longitudinal measurement invariance. METHODS: The research was conducted in 14 inpatient and 13 outpatient randomly se...",
