    "abstractSummaryId": "The problem of online game addiction demands public attention. Currently, many studies tend to be focused on efforts to reduce the level. However, there are very limited researches centered on discussing efforts to prevent this occurrence. This paper aims to examine various alternatives, in order to prevent this form of addiction, especially in adolescent’s that tend to be the most affected age group. In addition, there have been reports on its impact on several aspects of life, including health, psychologically, academically, socially and financially. Therefore, there is a need for preventive approaches, due...",
