      "Instrumen yang digunakan adalah SCS yang diadaptasi ke dalam Bahasa Indonesia dan diberi nama Skala Welas Diri (SWD).",
      "Berdasarkan hasil uji psikometrik menggunakan confirmatory factor analysis (CFA), uji validitas konstruk, dan koefisien Cronbach’s Alpha, ditemukan bahwa SWD memiliki validitas dan reliabilitas yang baik, serta memiliki model teoretis yang sama dengan SCS.",
