    "abstractSummaryId": "Self esteem merupakan sebuah pembentukan karakter mengenai diri sesorang dan merupakan faktor penting dalam perilaku langsung berkaitan dengan berbagai aspek dalam hidup. Tanpa dibekali self esteem, individu akan mengalami kesulitan untuk mengatasi tantangan hidup maupun untuk merasakan berbagai kebahagiaan dalam hidupnya. Ia juga mengatakan bahwa self esteem mengandung nilai keberlangsungan hidup (survival value) yang merupakan kebutuhan dasar manusia. Hal ini memungkinkan self esteem mampu memberikan sumbangan bermakna bagi proses kehidupan individu selanjutnya, maupun bagi perkembangan pribadi yang sehat. P...",
