    "abstractSummaryId": "People encounter many changes in the first year of college. It was related to adjustment’s problems, which was a serious problem that must be faced when entered college. Adaptation to new environment can make individual experienced stress. The various studies have shown that medical students experienced stress more higher than non-medical program students. Students who are experiencing extreme stress or depressed require serious attention cause it can have an adverse effect on learning process, achievement and even intent to suicide. This research involved 49 medical students. It took to determine the correlat...",
