      "Several types of plagiarism can be distinguished to the plagiarism motivation (intentional, unintentional, and inadvertent), how to do plagiarism (patchwriting, inappropriate paraphrasing, and summaries) and self-plagiarism (text recycling, redundant or dup...",
      "There are several reasons to do plagiarism, such as ease to get information via the internet, pressure on academic tasks, bad writing skill, hurry to write under pressure, lack of understanding how to rewrite the original reference, a misconception to under...",
