    "abstractSummaryId": "Burnout is commonly measured with the Maslach Burnout Inventory (MBI), which consists of three subscales measuring emotional exhaustion, personal accomplishment, and cynicism. We adapted the scale and then explored and confirmed the three dimensions on the Indonesian version named The Maslach-Trisni Burnout Inventory (M-TBI) with an exploratory analysis followed by Confirmatory Factor Analysis (CFA) from 822 workforces. The sensitivity for different job characteristics and demographic factors was established with analyses of variance and based on percentile scores of the subscales, three categories for burnout...",
