    "abstractSummaryId": "Tujuan dalam studi pendahuluan ini untuk melihat keyakinan serta atribusi individu dalam melihat tanggung jawab terkait permasalahan perubahan iklim dengan responden mahasiswa. Pengumpulan data menggunakan pertanyaan terbuka dengan melibatkan 267 responden. Data yang diperoleh dianalisis dengan menggunakan pendekatan analisis konten. Hasil penelitian menunjukkan bahwa 77% responden merasa familiar terkait dengan fenomena perubahan iklim dan 72% mahasiswa yang meyakini bahwa saat ini sedang mengalami permasalahan perubahan iklim yang dipersepsikan dengan 2 indikator terbesar yaitu suhu yang terasa meningkat dan...",
