    "abstractSummaryId": "Remaja merupakan masa kritis bagi perkembangan seseorang karena dihadapkan pada berbagai tugas perkembangan yang merupakan transisi dalam proses menuju dewasa. Kegagalan remaja dalam mencapai tugas perkembangan membuat remaja rentan mengalami gangguan psikologis seperti depresi. Penelitian ini bertujuan untuk mengetahui peran resiliensi dan empati terhadap gejala depresi pada remaja. Penelitian merupakan penelitian kuantitatif dengan desain cross-sectional . Pengukuran dilakukan dengan menggunakan adaptasi skala Center for Epidemiologic Studies Depression Scale Revised-10 (CESDR-10) untuk mengukur depresi, ada...",
