    "abstractSummaryId": "Fresh graduates need to have work readiness as one of the essential attributes. Work readiness is a condition when fresh graduates ready to succeed in the working world. In Indonesia, studies explaining the measurement scale of work readiness are still limited. This study aims to develop a work readiness scale for undergraduates, which is beneficial for companies, universities, and fresh graduates. The research sample consists of 118 fresh graduates, with no prior work experiences. After several examinations, the scale contains 49 items. As a result, the construct validity test using confirmatory factor analys...",
