    "abstractSummaryId": "Angka penderita gangguan mental di Indonesia terus meningkat secara signifikan dari tahun ke tahun. Namun, masyarakat pada negara-negara dengan pendapatan menengah ke bawah (termasuk Indonesia) cenderung untuk meminta bantuan penyembuh tradisional daripada tenaga profesional kesehatan mental dalam menangani gangguan mental. Penelitian ini bertujuan untuk mengetahui kontribusi yang diberikan oleh literasi kesehatan mental dan persepsi stigma publik terhadap sikap mencari bantuan profesional psikologi. Metode penelitian ini adalah kuantitatif, dengan desain penelitian regresi. Subjek pada penelitian ini adalah 3...",
