    "keyFindings": [
      "Subjek pada penelitian ini adalah 349 remaja berusia 18-24 tahun yang berdomisili di Kota Bandung.",
      "Data dari penelitian ini dianalisis dengan teknik analisis regresi linear sederhana.",
      "Hasil dari penelitian ini menunjukkan bahwa literasi kesehatan mental secara signifikan berkontribusi terhadap sikap mencari bantuan profesional psikologi (F = 63,130; p < 0,05), dan persepsi stigma publik terbukti tidak memberi kontribusi yang signifikan t..."
    ],
