    "sampleContext": "Detail jumlah & karakteristik partisipan tercantum lengkap pada teks penuh artikel DOI",
    "keyFindings": [
      "Therefore those three items have been eliminated.",
      "In addition, the coefficient of Cronbach's Alpha of TASES Indonesian version is highly reliable.",
      "Ultimately, the TASES Indonesian version consisting of 25-item within four dimensions has shown to be a reliable and valid measurement for academic self-efficacy in the Indonesian context."
    ],
