    "abstractSummaryId": "AbstractThe PERMA-Profiler is a well-being instrument which combines the hedonic and eudaimonic perspective of well-being. This instrument was developed based on well-being theory (Seligman, 2012) which explained well-being as a multidimensional construct, included positive emotion, engagement, relationship, meaning, and accomplishment (PERMA). This study aimed to adapt and examine the psychometric properties of the PERMA-Profiler in Indonesian people. The participants were 439 Indonesians, aged 17-63 years old (mean age = 30,82; SD = 10,00). Confirmatory Factor Analysis (CFA) was used to test the measurement...",
