    "abstractSummaryId": "The big five personality traits are the best acknowledged and most commonly used model in psychology. Therefore, many personality scales are developed based on this personality model. IPIP-BFM-50 is one of the open-source scales measuring big five personality that is widely used by the world researchers. This study aimed to adapt IPIP-BFM-50 into Indonesian and evaluate its psychometric properties. Adaptation was done by following the guidelines of the International Test Commission (ITC). The result shows that IPIP-BFM-50 Indonesia has Aiken's V index ranging from 0.71 - 0.98. Alpha reliability with n = 502 ra...",
