    "abstractSummaryId": "The Perceived Stress Scale (PSS-10) by Cohen is a popular tool for measuring stress from a psychological perspective. The PSS-10 measures the extent to which situations in a person's life are perceived as stressful. This study aims to evaluate the psychometric properties of the Perceived Stress Scale adapted into Indonesian. The PSS-10 has been translated into various languages, but no previous studies have specifically explored the psychometric properties of the PSS-10 in Indonesian. Additionally, this study seeks to test the construct invariance of the PSS-10 among students and workers. The respondents of th...",
