    "sampleContext": "Tercatat dalam abstrak artikel: N=259 (lihat detail kriteria sampel pada artikel asli)",
    "keyFindings": [
      "The AVE value of 0.38 for student participants was considered low, with a CR value of 0.81, which is quite good.",
      "For employee participants, the AVE value was 0.58 and the CR value was 0.93, both of which were good.",
      "Based on the multigroup CFA analysis test, there are differences in the factor structure of the PSS-10 between students and employees, where these differences lie in how the two groups respond to and interpret the items of the PSS-10."
    ],
