    "abstractSummaryId": "The purpose of this study was to determine the effect of employee engagement and burnout on the perception of work-life balance, particularly on blue-collar workers. The study sample comprised of 91 employees of the production section (blue-collar workers) in a multinational company in Jababeka-Cikarang. Sampling was carried out using a stratified technique of proportional approach. The instruments used in this study are The Utrecht Work Engagement Scale (UWES), Maslach Burnout Inventory (MBI-GS), and Work-Life Balance Scale. The study used primary data collection through survey method and secondary data from...",
