    "abstractSummaryId": "Beliefs and goals in parenting are influenced by the expectations of society or local culture. Therefore, the measurement of parenting should be developed from a contextual perspective. The development of the measurement conducted inductively which started with the phase of indigenous concept exploration. The participants are parents living in a particular area, having a local ethnic identity, using local language and customs in their daily lives. The method of data collection is an interview or focus group discussion (FGD), with questions that refer to the parenting element according to Darling & Steinberg. T...",
