    "abstractSummaryId": "AbstractOne of the critical subjects in school that needs to be assessed is a science subject. Without a science subject, students cannot observe and understand a phenomenon on earth. However, results from an international study such as Trends International in Mathematics and Science (TIMSS), students in Indonesia performed poorly compared to students from another country. Furthermore, science is one of the essential education for children as it included in the STEM Education (Science, Technology, Engineering and Mathematics). From some empirical evidence, student’s attitude and self-efficacy (beliefs about th...",
    "methodology": "Studi Longitudinal",
    "sampleContext": "Detail jumlah & karakteristik partisipan tercantum lengkap pada teks penuh artikel DOI",
    "keyFindings": [
      "Secara lebih spesifik, sikap terhadap sains memiliki dampak paling signifikan terhadap pencapaian prestasi sains, pengaruh ini lebih besar dibandingkan pengaruh dari efikasi diri.",
      "Namun, yang menarik adalah pola pengaruh dari tiap prediktor tersebut berbeda – beda dampaknya terhadap prestasi sains.",
      "Aspek praktis dari hasil penelitian ini akan dibahas pada bagian diskusi."
    ],
    "implications": "Rujukan primer terbuka (JP3I (Jurnal Pengukuran Psikologi dan Pendidikan Indonesia), 2020); gunakan tautan DOI untuk verifikasi data lengkap, tabel statistik, dan teks penuh artikel.",
