    "abstractSummaryId": "The quality of marriage gain the attention of researchers for a long time. Various studies have been done, by placing the marital quality as an independent variable or dependent variable. Although research on marital quality has been done for a long time with a wide range of variables, conceptually, the results are not quite satisfactory. This article aimed to describe literature review on the concept of marital quality. The literature search results define quality of marriage as the level of excellence in marriage based on certain characteristics. These particular characteristics or criteria may vary from reg...",
