    "abstractSummaryId": "Measurement instruments that have satisfactory psychometric properties are needed to improve mental health research and services, especially in the effort to measure, identify, and monitor the psychological problems experienced by individuals. The purpose of this study is to examine the psychometric properties of the Indonesian version of the Depression Anxiety Stress Scale (DASS). The study involved 1,922 participants from Surabaya aged between 16 and 26. The data were obtained using the convenience sampling method. Testing of the factor structure, reliability, and measurement invariance of the Indonesian DAS...",
